301	    /**
302	     * Rejects an owner whose {@code firstName}, {@code lastName}, {@code address}, {@code city} or
303	     * {@code telephone} is missing or blank (including whitespace-only values that Bean Validation
304	     * does not catch). The names of all offending fields are collected so the caller receives a
305	     * 400 response whose {@code errors} array lists each one.
306	     */
307	    private void validateRequiredFields(OwnerFieldsDto ownerFieldsDto) {
308	        List<String> missingFields = new ArrayList<>();
309	        if (isBlank(ownerFieldsDto.getFirstName())) {
310	            missingFields.add("firstName");
311	        }
312	        if (isBlank(ownerFieldsDto.getLastName())) {
313	            missingFields.add("lastName");
314	        }
315	        if (isBlank(ownerFieldsDto.getAddress())) {
316	            missingFields.add("address");
317	        }
318	        if (isBlank(ownerFieldsDto.getCity())) {
319	            missingFields.add("city");
320	        }
321	        if (isBlank(ownerFieldsDto.getTelephone())) {
322	            missingFields.add("telephone");
323	        }
324	        if (!missingFields.isEmpty()) {
325	            throw new InvalidOwnerFieldsException(missingFields);
326	        }
327	    }
328	
329	    private static boolean isBlank(String value) {
330	        return value == null || value.trim().isEmpty();
331	    }
332	
333	    /**
334	     * Normalizes an owner's {@code address} on create and writes the canonical form back onto the
335	     * request so it is what gets validated, compared, stored and returned. The value is trimmed,
336	     * runs of internal whitespace are collapsed to a single space, the result is upper-cased and
337	     * common street-type abbreviations are expanded as whole tokens ({@code ST}->{@code STREET},
338	     * {@code RD}->{@code ROAD}, {@code AVE}->{@code AVENUE}). Running before the required-field check
339	     * means an address that is blank after normalization is rejected like a missing one.
340	     */
341	    private void normalizeAddress(OwnerFieldsDto ownerFieldsDto) {
342	        ownerFieldsDto.setAddress(canonicalAddress(ownerFieldsDto.getAddress()));
343	    }
344	
345	    /**
346	     * Returns the canonical form of an address: trimmed, internal whitespace runs collapsed to a
347	     * single space, upper-cased, with common street-type abbreviations expanded as whole tokens. A
348	     * {@code null} value returns {@code null}. The transform is idempotent, so an already-canonical
349	     * address is returned unchanged, making it safe to apply to stored values during comparison.
350	     */
351	    private static String canonicalAddress(String address) {
352	        if (address == null) {
353	            return null;
354	        }
355	        String collapsed = address.trim().replaceAll("\\s+", " ").toUpperCase(Locale.ROOT);
356	        if (collapsed.isEmpty()) {
357	            return "";
358	        }
359	        String[] tokens = collapsed.split(" ");
360	        StringBuilder sb = new StringBuilder(collapsed.length());
361	        for (int i = 0; i < tokens.length; i++) {
362	            if (i > 0) {
363	                sb.append(' ');
364	            }
365	            sb.append(ADDRESS_ABBREVIATIONS.getOrDefault(tokens[i], tokens[i]));
366	        }
367	        return sb.toString();
368	    }
