488	    /**
489	     * Rejects creating an owner in a city that has reached capacity: a city that already contains
490	     * {@value #MAX_OWNERS_PER_CITY} or more owners cannot take another one. Existing owners are
491	     * counted with a case-insensitive match on {@code city}, the same way {@link #assignCustomerCode}
492	     * groups a city. A city at or over the limit results in a 409 response naming {@code city}.
493	     */
494	    private void rejectCityAtCapacity(OwnerFieldsDto ownerFieldsDto) {
495	        String city = ownerFieldsDto.getCity();
496	        int count = 0;
497	        for (Owner existing : this.clinicService.findAllOwners()) {
498	            if (city.equalsIgnoreCase(existing.getCity())) {
499	                count++;
500	            }
501	        }
502	        if (count >= MAX_OWNERS_PER_CITY) {
503	            throw new OwnerCityAtCapacityException(city);
504	        }
505	    }
506	
507	    /**
508	     * Rejects creating an owner once {@value #MAX_OWNERS_PER_DAY} or more owners already carry the
509	     * given adjusted business-day {@code registrationDate}, counted by an exact match. The date has
510	     * already been resolved and rolled forward off a weekend by {@link #resolveRegistrationDate}, so
511	     * the limit is enforced per business day. A day at or over the limit results in a 429 response.
512	     */
513	    private void rejectDailyLimitReached(LocalDate registrationDate) {
514	        int count = 0;
515	        for (Owner existing : this.clinicService.findAllOwners()) {
516	            if (registrationDate.equals(existing.getRegistrationDate())) {
517	                count++;
518	            }
519	        }
520	        if (count >= MAX_OWNERS_PER_DAY) {
521	            throw new DailyOwnerLimitReachedException(registrationDate);
522	        }
523	    }
